(816935, 90674, 4517, '<td valign="top">Getting very popular this shot :)</td>', 'Getting very popular this shot :)', '2004-07-19 13:53:13.000000', NULL, 1),
(816936, 90988, 7628, '<td valign="top">This crazy angle makes the viewer grab on to a table to stablilize - nice presentation!  Wish there were more detail in the sculpture - hard to do against the bright sky, but with the advanced rules you could try a little burning/dodging. 7</td>', 'This crazy angle makes the viewer grab on to a table to stablilize - nice presentation!  Wish there were more detail in the sculpture - hard to do against the bright sky, but with the advanced rules you could try a little burning/dodging. 7', '2004-07-19 13:53:30.000000', NULL, 1),
(816938, 92011, 7628, '<td valign="top">Nice composition, nice details in the feather even though they are bright. Wish the background weren''t so busy - could you blur it a bit or darken it?</td>', 'Nice composition, nice details in the feather even though they are bright. Wish the background weren''t so busy - could you blur it a bit or darken it?', '2004-07-19 13:54:31.000000', NULL, 1),
(816940, 92033, 4517, '<td valign="top">Striking photo. Well done 10</td>', 'Striking photo. Well done 10', '2004-07-19 13:55:56.000000', NULL, 1),
(816941, 91973, 7628, '<td valign="top">Nice! Funny!  Fun composition with the one sharp head backed by the multitude of other.  Nice use of narrow DOF.  Nice color, light.  A top ten IMO!  9</td>', 'Nice! Funny!  Fun composition with the one sharp head backed by the multitude of other.  Nice use of narrow DOF.  Nice color, light.  A top ten IMO!  9', '2004-07-19 13:56:03.000000', NULL, 1),
(816942, 91366, 18197, '<td valign="top">This is a very nice image well composed and well shot. I am bothered by the jagged artifacts along the top edges of the eggs and in some of the reflected highlights on the bowl. It could be perfectly natural, but the shadow on the vertical egg looks out of synch with the shadows on the other eggs. Otherwise a 10.</td>', 'This is a very nice image well composed and well shot. I am bothered by the jagged artifacts along the top edges of the eggs and in some of the reflected highlights on the bowl. It could be perfectly natural, but the shadow on the vertical egg looks out of synch with the shadows on the other eggs. Otherwise a 10.', '2004-07-19 13:56:37.000000', NULL, 1),
(816946, 92052, 7628, '<td valign="top">Lovely clear and precise.  Good color choices, fine lighting.  I like the composition with the one flower down.  9</td>', 'Lovely clear and precise.  Good color choices, fine lighting.  I like the composition with the one flower down.  9', '2004-07-19 13:57:08.000000', NULL, 1),
(816947, 92113, 18197, '<td valign="top">This is a beautiful image. Subject matter is fantastic, colors terrific, balance and composition is virtually perfect. Great image.</td>', 'This is a beautiful image. Subject matter is fantastic, colors terrific, balance and composition is virtually perfect. Great image.', '2004-07-19 13:58:23.000000', NULL, 1),
(816949, 91909, 7628, '<td valign="top">pretty light - the gold and blue go so well together.  I like the rocks and flowers inthe foreground - subtle but make a nice frame.  The line on illuminted masts make a wonderful center line, and the sky hold its own with dramatic clouds. well done! 8</td>', 'pretty light - the gold and blue go so well together.  I like the rocks and flowers inthe foreground - subtle but make a nice frame.  The line on illuminted masts make a wonderful center line, and the sky hold its own with dramatic clouds. well done! 8', '2004-07-19 13:58:53.000000', NULL, 1),
(816950, 92164, 7628, '<td valign="top">Unusual sillouette! Your subject looks like a sculpture, nice a sharp.  The wheel looks like a head in wome modern art theme,  Inventive. 7</td>', 'Unusual sillouette! Your subject looks like a sculpture, nice a sharp.  The wheel looks like a head in wome modern art theme,  Inventive. 7', '2004-07-19 14:00:10.000000', NULL, 1),
(816951, 91664, 7628, '<td valign="top">This would be a good postcard shot.  The flowers make a great foreground.</td>', 'This would be a good postcard shot.  The flowers make a great foreground.', '2004-07-19 14:01:01.000000', NULL, 1),
(816952, 92222, 4517, '<td valign="top">Well it meets the chellenge but i think you need to get away from the computer with your camera ;)</td>', 'Well it meets the chellenge but i think you need to get away from the computer with your camera ;)', '2004-07-19 14:01:08.000000', NULL, 1),
(816954, 91222, 18197, '<td valign="top">A fine image, well composed and focused. The border detracted from the image in my opinion.</td>', 'A fine image, well composed and focused. The border detracted from the image in my opinion.', '2004-07-19 14:02:11.000000', NULL, 1),
(816955, 91097, 23454, '<td valign="top">Great photo. The color, composition, focus, DOF, lighting is all superb. If the text "Absolutely Straight" had been centered above the tee, it would have made a much stronger impact. 9</td>', 'Great photo. The color, composition, focus, DOF, lighting is all superb. If the text "Absolutely Straight" had been centered above the tee, it would have made a much stronger impact. 9', '2004-07-19 14:03:21.000000', NULL, 1),
(816956, 91803, 7628, '<td valign="top">Fun and magical.  Having the mysterious person here works better than the balancing trick would on its own.  I like the purple drapes, Wish the lighting weren''t so harsh on the face.  Good illusion (or is it real?)</td>', 'Fun and magical.  Having the mysterious person here works better than the balancing trick would on its own.  I like the purple drapes, Wish the lighting weren''t so harsh on the face.  Good illusion (or is it real?)', '2004-07-19 14:03:35.000000', NULL, 1),
(816957, 92165, 18197, '<td valign="top">I like the image, the high contrast, superb focus, the improbable subject and the fact that you can just see the actor in this drama in the background. Well done.</td>', 'I like the image, the high contrast, superb focus, the improbable subject and the fact that you can just see the actor in this drama in the background. Well done.', '2004-07-19 14:03:53.000000', NULL, 1),
(816958, 91033, 7628, '<td valign="top">Ilike the background, adds meaning to the abstract object.  The reflections have nice colors. but are a bit distracting.  I might have cropped more top and bottom t pull the composition together more.</td>', 'Ilike the background, adds meaning to the abstract object.  The reflections have nice colors. but are a bit distracting.  I might have cropped more top and bottom t pull the composition together more.', '2004-07-19 14:05:47.000000', NULL, 1),
(816959, 92224, 4517, '<td valign="top">Don`t you just hate it when you spot a typo after the deadline :)</td>', 'Don`t you just hate it when you spot a typo after the deadline :)', '2004-07-19 14:06:11.000000', NULL, 1),
(816960, 92157, 7628, '<td valign="top">Fun double meaning.  I like the solid balance of the composition.  The choice of a dark dark sky is good.  Nice detail in the architecture, forms and shadows. 7</td>', 'Fun double meaning.  I like the solid balance of the composition.  The choice of a dark dark sky is good.  Nice detail in the architecture, forms and shadows. 7', '2004-07-19 14:07:39.000000', NULL, 1),
(816963, 91789, 7628, '<td valign="top">I like this photo from the first I glimpsed it.  I keep coming back to it.  Gritty texture, good use of narrow DOF and lighting to differentiate between subject and background.  I like the balance here. 7</td>', 'I like this photo from the first I glimpsed it.  I keep coming back to it.  Gritty texture, good use of narrow DOF and lighting to differentiate between subject and background.  I like the balance here. 7', '2004-07-19 14:09:50.000000', NULL, 1),
(816967, 92037, 7628, '<td valign="top">Very nice compostion, balanced indeed and pleasant to look out.  Lighting is a bit flat, but dramatic architeture makes up for it.  I like the added balance between present and past as well.</td>', 'Very nice compostion, balanced indeed and pleasant to look out.  Lighting is a bit flat, but dramatic architeture makes up for it.  I like the added balance between present and past as well.', '2004-07-19 14:12:06.000000', NULL, 1),
(816968, 91956, 4517, '<td valign="top">Good idea. Maybe closer in on the bubble to cut out some of the less interesting part.</td>', 'Good idea. Maybe closer in on the bubble to cut out some of the less interesting part.', '2004-07-19 14:12:12.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(816969, 91976, 13203, '<td valign="top">Love this shot!  It all fits together with the title!  Creative.</td>', 'Love this shot!  It all fits together with the title!  Creative.', '2004-07-19 14:14:20.000000', NULL, 1),
(816971, 92137, 7628, '<td valign="top">High drama and contrast!  The sky is a bit grainy as a result of the pumped up saturation.  But the overall effect is pleasing.  It is a great sculpture to give a feeling for acheiving balance.  I like how you''ve put it all to one side and used the cloud to balance the composition. 7</td>', 'High drama and contrast!  The sky is a bit grainy as a result of the pumped up saturation.  But the overall effect is pleasing.  It is a great sculpture to give a feeling for acheiving balance.  I like how you''ve put it all to one side and used the cloud to balance the composition. 7', '2004-07-19 14:14:31.000000', NULL, 1),
(816974, 92223, 7628, '<td valign="top">Wish the lighting on the hand were as good as the lighting on the berry. The shadow of the berry is distracting and the hand is a bit too red.  That is a perfect berry! Is it stuck to the background or did you catch it falling?  It is so sharp I''m assuming it must be stuck.  Fun image,</td>', 'Wish the lighting on the hand were as good as the lighting on the berry. The shadow of the berry is distracting and the hand is a bit too red.  That is a perfect berry! Is it stuck to the background or did you catch it falling?  It is so sharp I''m assuming it must be stuck.  Fun image,', '2004-07-19 14:17:21.000000', NULL, 1),
(816977, 92165, 4517, '<td valign="top">Great shot but a long way off the record. I think the records about 8. Good luck 9</td>', 'Great shot but a long way off the record. I think the records about 8. Good luck 9', '2004-07-19 14:19:04.000000', NULL, 1),
(816979, 92155, 7628, '<td valign="top">I really enjoy this.  I like the multiple levels created by the flowers floating above the dark depths of the leaves.  Very sharp, nice range of grays. 8</td>', 'I really enjoy this.  I like the multiple levels created by the flowers floating above the dark depths of the leaves.  Very sharp, nice range of grays. 8', '2004-07-19 14:19:54.000000', NULL, 1),
(816981, 92220, 3039, '<td valign="top">Excellent perspective</td>', 'Excellent perspective', '2004-07-19 14:20:41.000000', NULL, 1),
(816982, 91877, 7628, '<td valign="top">What a graceful motion/position you''ve captured.  I like the sweep on the lines in the ice that mirror the movement of the skater.  Wish that black gap weren''t there!!</td>', 'What a graceful motion/position you''ve captured.  I like the sweep on the lines in the ice that mirror the movement of the skater.  Wish that black gap weren''t there!!', '2004-07-19 14:20:48.000000', NULL, 1),
(816984, 91797, 4517, '<td valign="top">Border very distracting.</td>', 'Border very distracting.', '2004-07-19 14:22:37.000000', NULL, 1),
(816985, 90674, 3039, '<td valign="top">Very well done! Good theme.</td>', 'Very well done! Good theme.', '2004-07-19 14:22:51.000000', NULL, 1),
(816986, 91033, 4517, '<td valign="top">I like the colours and background. 9</td>', 'I like the colours and background. 9', '2004-07-19 14:23:13.000000', NULL, 1),
(816990, 90886, 4517, '<td valign="top">Great pic but she looks a little cutout.</td>', 'Great pic but she looks a little cutout.', '2004-07-19 14:25:14.000000', NULL, 1),
(816991, 92075, 3039, '<td valign="top">Great Shot! 11:08 ???????</td>', 'Great Shot! 11:08 ???????', '2004-07-19 14:25:24.000000', NULL, 1),
(816992, 91366, 4517, '<td valign="top">Quality photo. 10</td>', 'Quality photo. 10', '2004-07-19 14:25:43.000000', NULL, 1),
(817000, 91746, 12661, '<td valign="top">Wow, at first I thought this was a water drop shot. Nice choice in using clear thumbtacks. I love the way the light shines through them to creat concentric circles. Excellent composition and topic.</td>', 'Wow, at first I thought this was a water drop shot. Nice choice in using clear thumbtacks. I love the way the light shines through them to creat concentric circles. Excellent composition and topic.', '2004-07-19 14:31:37.000000', NULL, 1),
(817002, 92084, 3039, '<td valign="top">clever!</td>', 'clever!', '2004-07-19 14:32:40.000000', NULL, 1),
(817003, 92060, 3039, '<td valign="top">Wondeful!</td>', 'Wondeful!', '2004-07-19 14:33:39.000000', NULL, 1),
(817007, 91987, 4517, '<td valign="top">A lot of effort has gone into this photo. Imo the best i`ve seen on DPC for a long time. Outstanding result. If this doesn`t win i`ll eat my camera. 10++</td>', 'A lot of effort has gone into this photo. Imo the best i`ve seen on DPC for a long time. Outstanding result. If this doesn`t win i`ll eat my camera. 10++', '2004-07-19 14:36:05.000000', NULL, 1),
(817008, 91783, 4517, '<td valign="top">Very nice shot. Favorite so far. 9</td>', 'Very nice shot. Favorite so far. 9', '2004-07-19 14:36:49.000000', NULL, 1),
(817010, 92052, 3039, '<td valign="top">Outstanding!</td>', 'Outstanding!', '2004-07-19 14:37:52.000000', NULL, 1),
(817011, 92181, 7628, '<td valign="top">What a great action shot!  I like the facial expressions, the balancein the composition, the loss of balance in the subject too, and I like te sepia tone. 9</td>', 'What a great action shot!  I like the facial expressions, the balancein the composition, the loss of balance in the subject too, and I like te sepia tone. 9', '2004-07-19 14:38:07.000000', NULL, 1),
(817019, 91976, 12661, '<td valign="top">Spectacular composition. That cat certainly adds a lot to the overall ''balance'' of the photo.</td>', 'Spectacular composition. That cat certainly adds a lot to the overall ''balance'' of the photo.', '2004-07-19 14:43:38.000000', NULL, 1),
(817029, 91985, 18349, '<td valign="top">Thanks...now I''m gonna have that song stuck in my craw all day!  :o)<br/>Good take on the challenge.  Wonder how many "doesn''t meet the challenge" comments you''ll get???  Well done, IMHO anyway!  :o)</td>', 'Thanks...now I''m gonna have that song stuck in my craw all day!  :o)Good take on the challenge.  Wonder how many "doesn''t meet the challenge" comments you''ll get???  Well done, IMHO anyway!  :o)', '2004-07-19 14:56:07.000000', NULL, 1),
(817030, 92113, 12661, '<td valign="top">This must be the work of geewhy. That lift never ceases to amaze me. I like this view of it and the vibrance of the colors is excellent.</td>', 'This must be the work of geewhy. That lift never ceases to amaze me. I like this view of it and the vibrance of the colors is excellent.', '2004-07-19 15:01:24.000000', NULL, 1),
(817034, 91803, 19608, '<td valign="top">How do you spell RIBBON?</td>', 'How do you spell RIBBON?', '2004-07-19 15:04:30.000000', NULL, 1),
(817036, 91225, 19608, '<td valign="top">Whoa!  Great job.</td>', 'Whoa!  Great job.', '2004-07-19 15:05:15.000000', NULL, 1),
(817037, 92165, 19608, '<td valign="top">Perfect lighting - just enough of the face to add interest.  This should score very high.</td>', 'Perfect lighting - just enough of the face to add interest.  This should score very high.', '2004-07-19 15:06:38.000000', NULL, 1),
(817039, 91366, 19608, '<td valign="top">Excellent composition, choice of colors and background.  Side lighting very well done.Not crazy about the border.</td>', 'Excellent composition, choice of colors and background.  Side lighting very well done.Not crazy about the border.', '2004-07-19 15:07:55.000000', NULL, 1),
(817040, 92113, 21362, '<td valign="top">Very strange. I''m curious to find out where this is and what exactly that thing does! Nice photo, good color and composition.</td>', 'Very strange. I''m curious to find out where this is and what exactly that thing does! Nice photo, good color and composition.', '2004-07-19 15:08:30.000000', NULL, 1),
(817043, 92052, 19608, '<td valign="top">Lovely colors that compliment each other very well.  This should finish way up in the pack!</td>', 'Lovely colors that compliment each other very well.  This should finish way up in the pack!', '2004-07-19 15:09:24.000000', NULL, 1),
(817046, 91987, 19608, '<td valign="top">A real WOWSER!   Who would ever think about using a fish-eye for a wedding shot!!?  This is a perfect example of when the "rules do not work'' - the horizon is dead center (and it is PERFECT), the couple is dead center (and it is PERFECT.)  Great job.</td>', 'A real WOWSER!   Who would ever think about using a fish-eye for a wedding shot!!?  This is a perfect example of when the "rules do not work'' - the horizon is dead center (and it is PERFECT), the couple is dead center (and it is PERFECT.)  Great job.', '2004-07-19 15:13:51.000000', NULL, 1),
(817048, 92011, 23373, '<td valign="top">Might be better is not cropped with the subject in dead center</td>', 'Might be better is not cropped with the subject in dead center', '2004-07-19 15:15:32.000000', NULL, 1),
(817050, 91984, 21362, '<td valign="top">I tried to do one of these for my entries and it was way harder than I thought it would be. So consider me impressed! I think taking the photo at a slight angle would have made this more interesting.</td>', 'I tried to do one of these for my entries and it was way harder than I thought it would be. So consider me impressed! I think taking the photo at a slight angle would have made this more interesting.', '2004-07-19 15:15:44.000000', NULL, 1),
(817051, 91033, 19608, '<td valign="top">Magical.  Great colors, lighting, and background combine to make this simple image one of the best in the challenge.</td>', 'Magical.  Great colors, lighting, and background combine to make this simple image one of the best in the challenge.', '2004-07-19 15:16:22.000000', NULL, 1),
(817053, 91666, 19608, '<td valign="top">Wonderful lighting and background make this a very stong image.</td>', 'Wonderful lighting and background make this a very stong image.', '2004-07-19 15:17:29.000000', NULL, 1),
(817055, 92207, 19608, '<td valign="top">Very well done.  Lighting is great - composition could not be better.  Black background was a perfect choice.  The worst part of the submission is the title.</td>', 'Very well done.  Lighting is great - composition could not be better.  Black background was a perfect choice.  The worst part of the submission is the title.', '2004-07-19 15:19:35.000000', NULL, 1),
(817056, 92131, 23373, '<td valign="top">Not certain what this has to do witht he challenge.</td>', 'Not certain what this has to do witht he challenge.', '2004-07-19 15:19:35.000000', NULL, 1),
(817057, 92037, 23373, '<td valign="top">Yes symetry, balance???</td>', 'Yes symetry, balance???', '2004-07-19 15:20:19.000000', NULL, 1),
(817058, 91585, 19608, '<td valign="top">Perfect color for the background.  A very simple but effective balacing act. Nice side lighting.</td>', 'Perfect color for the background.  A very simple but effective balacing act. Nice side lighting.', '2004-07-19 15:20:46.000000', NULL, 1),
(817059, 91910, 19608, '<td valign="top">Great composition - I like the way you''ve use both top corners.  Nice lighting as well.  White background works very well.</td>', 'Great composition - I like the way you''ve use both top corners.  Nice lighting as well.  White background works very well.', '2004-07-19 15:22:23.000000', NULL, 1),
(817064, 92223, 19608, '<td valign="top">Excellent captuure.  The blue background works well with the berry and hand colors.  A bit weak on "balance" - but still a nice shot.</td>', 'Excellent captuure.  The blue background works well with the berry and hand colors.  A bit weak on "balance" - but still a nice shot.', '2004-07-19 15:23:47.000000', NULL, 1),
(817066, 92176, 23373, '<td valign="top">Great scene.  Might consider cropping more tightly and fixing the sky - strange grey in the top of the clouds.</td>', 'Great scene.  Might consider cropping more tightly and fixing the sky - strange grey in the top of the clouds.', '2004-07-19 15:24:30.000000', NULL, 1),
(817069, 91746, 22689, '<td valign="top">At least something different , interesting composition !</td>', 'At least something different , interesting composition !', '2004-07-19 15:24:56.000000', NULL, 1),
(817070, 91909, 23373, '<td valign="top">I love the sky &amp; contrast to the orange light.  Might consider cloning out the flowers in the foreground or cropping out the rock completely for an even more powerful image.</td>', 'I love the sky & contrast to the orange light.  Might consider cloning out the flowers in the foreground or cropping out the rock completely for an even more powerful image.', '2004-07-19 15:26:43.000000', NULL, 1),
(817072, 91988, 10643, '<td valign="top">the green border is distracting. something slightly rougher, if you must use a border, might have fit better with the rough/used appearance of the stereo. also, having the lights be the only color in the image gives it a nice black and white feel. the border takes that away.</td>', 'the green border is distracting. something slightly rougher, if you must use a border, might have fit better with the rough/used appearance of the stereo. also, having the lights be the only color in the image gives it a nice black and white feel. the border takes that away.', '2004-07-19 15:27:31.000000', NULL, 1),
(817073, 92057, 19608, '<td valign="top">Colorful and effective.</td>', 'Colorful and effective.', '2004-07-19 15:28:21.000000', NULL, 1),
(817075, 92216, 10643, '<td valign="top">beautiful shot. not sure how well it says balance, but it''s a lovely picture. my dad loves lighthouse pictures and I hope this will be a print if it''s high-res enough.</td>', 'beautiful shot. not sure how well it says balance, but it''s a lovely picture. my dad loves lighthouse pictures and I hope this will be a print if it''s high-res enough.', '2004-07-19 15:29:06.000000', NULL, 1),
(817079, 91747, 23373, '<td valign="top">Very nice, great DOF and color.  Have you considered cropping so the subject would be off center.</td>', 'Very nice, great DOF and color.  Have you considered cropping so the subject would be off center.', '2004-07-19 15:30:27.000000', NULL, 1),
(817080, 91746, 19608, '<td valign="top">A very interesting idea - at first glace the thunbnail appears to be another verion of those "water shots."  Well done.</td>', 'A very interesting idea - at first glace the thunbnail appears to be another verion of those "water shots."  Well done.', '2004-07-19 15:30:32.000000', NULL, 1),
(817081, 92161, 23373, '<td valign="top">Wonderful scene.  Would pefer a but more tonal variation.</td>', 'Wonderful scene.  Would pefer a but more tonal variation.', '2004-07-19 15:32:23.000000', NULL, 1),
(817083, 91366, 327, '<td valign="top">Nice light, good idea and execution. Just looks a bit over sharpened.</td>', 'Nice light, good idea and execution. Just looks a bit over sharpened.', '2004-07-19 15:35:00.000000', NULL, 1),
(817084, 92010, 23373, '<td valign="top">Might try to crop with the subject off center.</td>', 'Might try to crop with the subject off center.', '2004-07-19 15:35:18.000000', NULL, 1),
(817085, 92157, 327, '<td valign="top">Awesome coloring, composition and focus. 9 from me.</td>', 'Awesome coloring, composition and focus. 9 from me.', '2004-07-19 15:35:57.000000', NULL, 1),
(817086, 91747, 327, '<td valign="top">Looks like Hood River?? Very nice.9</td>', 'Looks like Hood River?? Very nice.9', '2004-07-19 15:36:26.000000', NULL, 1),
(817087, 91987, 327, '<td valign="top">Wonderful shot.</td>', 'Wonderful shot.', '2004-07-19 15:38:19.000000', NULL, 1),
(817091, 91976, 23373, '<td valign="top">Great shot, wonderful light and focus.  I like everything about this shot.</td>', 'Great shot, wonderful light and focus.  I like everything about this shot.', '2004-07-19 15:47:54.000000', NULL, 1),
(817093, 92206, 16106, '<td valign="top">Bit too dark and perhaps too much USM. I like the way the red comes through the glass.</td>', 'Bit too dark and perhaps too much USM. I like the way the red comes through the glass.', '2004-07-19 15:50:53.000000', NULL, 1),
(817096, 91619, 23373, '<td valign="top">Like the tonal variation.  Might look better with a thinner black grame.</td>', 'Like the tonal variation.  Might look better with a thinner black grame.', '2004-07-19 15:51:58.000000', NULL, 1),
(817102, 91761, 19608, '<td valign="top">Very well done.  They even look like they''re having fun!</td>', 'Very well done.  They even look like they''re having fun!', '2004-07-19 16:05:30.000000', NULL, 1),
(817104, 91838, 21058, '<td valign="top">it''s genetic this attitude i think... ;)</td>', 'it''s genetic this attitude i think... ;)', '2004-07-19 16:07:47.000000', NULL, 1),
(817105, 91667, 19608, '<td valign="top">Nice scene.  On my monitor, the colors - especially the green - seem overly saturated.</td>', 'Nice scene.  On my monitor, the colors - especially the green - seem overly saturated.', '2004-07-19 16:08:05.000000', NULL, 1),
(817106, 92164, 21058, '<td valign="top">wonderful picture with a great sky and a beautiful silhouette...</td>', 'wonderful picture with a great sky and a beautiful silhouette...', '2004-07-19 16:08:22.000000', NULL, 1),
(817114, 92078, 16106, '<td valign="top">I think a portrait orientation would have better emphisised the lifting going on here.</td>', 'I think a portrait orientation would have better emphisised the lifting going on here.', '2004-07-19 16:22:48.000000', NULL, 1),
(817146, 92075, 8367, '<td valign="top">You put that title so you''d get comments, didn''t you? It worked!  Looks like 11:13ish to me. I like the centered composition. The lack of background color looks okay with this photo. IMO, it allows the viewer to focus on the subject without distractions. Speaking of distractions, the border is somewhat on the thick side. A more conservative approach would compliment it better. Overall, I like your subject choice and your presentation of it.</td>', 'You put that title so you''d get comments, didn''t you? It worked!  Looks like 11:13ish to me. I like the centered composition. The lack of background color looks okay with this photo. IMO, it allows the viewer to focus on the subject without distractions. Speaking of distractions, the border is somewhat on the thick side. A more conservative approach would compliment it better. Overall, I like your subject choice and your presentation of it.', '2004-07-19 17:10:01.000000', NULL, 1),
(817167, 91225, 16106, '<td valign="top">Good composition and focus, but I wish you had a blacker black and a whiter white on the B&amp;W conversion.</td>', 'Good composition and focus, but I wish you had a blacker black and a whiter white on the B&W conversion.', '2004-07-19 17:37:43.000000', NULL, 1),
