(817824, 92052, 16046, '<td valign="top">Cute, and well done.</td>', 'Cute, and well done.', '2004-07-20 04:44:36.000000', NULL, 1),
(817825, 91366, 16046, '<td valign="top">Great work here, nice color.</td>', 'Great work here, nice color.', '2004-07-20 04:45:17.000000', NULL, 1),
(817826, 92176, 16046, '<td valign="top">Super find, well done.</td>', 'Super find, well done.', '2004-07-20 04:46:40.000000', NULL, 1),
(817827, 92212, 16046, '<td valign="top">Great action shot!</td>', 'Great action shot!', '2004-07-20 04:47:27.000000', NULL, 1),
(817834, 92113, 16301, '<td valign="top">Nice contrasting colors in the scene, nothing can say balance more than that. Good luck...</td>', 'Nice contrasting colors in the scene, nothing can say balance more than that. Good luck...', '2004-07-20 05:18:23.000000', NULL, 1),
(817836, 91803, 10170, '<td valign="top">Absolutely love it, and really great lighting.</td>', 'Absolutely love it, and really great lighting.', '2004-07-20 05:22:35.000000', NULL, 1),
