(817840, 91803, 16301, '<td valign="top">Did Heida give you her purple cloth? :P<br/> <br/>Very creative and original idea, I hope you can share how you did it when the challenge is done. (10)<br/> <br/>Good luck...</td>', 'Did Heida give you her purple cloth? :P Very creative and original idea, I hope you can share how you did it when the challenge is done. (10) Good luck...', '2004-07-20 05:25:05.000000', NULL, 1),
(817842, 92209, 10170, '<td valign="top">Sensational - has to be a ribbon.</td>', 'Sensational - has to be a ribbon.', '2004-07-20 05:28:10.000000', NULL, 1),
