INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(817859, 91097, 17233, '<td valign="top">Lighting, DOF, composition all great. Well done (9)</td>', 'Lighting, DOF, composition all great. Well done (9)', '2004-07-20 06:14:52.000000', NULL, 1),
(817861, 92084, 17233, '<td valign="top">Love the lighting and composition. The black background sets off the subject(s) very nicely. Well done (9)</td>', 'Love the lighting and composition. The black background sets off the subject(s) very nicely. Well done (9)', '2004-07-20 06:17:49.000000', NULL, 1),
(817863, 91222, 17233, '<td valign="top">I love this shot. Simple composition, beautiful soft lighting and I even like the frame. Well done (9)</td>', 'I love this shot. Simple composition, beautiful soft lighting and I even like the frame. Well done (9)', '2004-07-20 06:20:15.000000', NULL, 1),
(817867, 91987, 17233, '<td valign="top">THE perfect wedding shot. I love the wide angle distortion and the composition and burning set this image apart from a lot of the others in this challenge. Beautiful contrast and the sepia tones work very well here. Great placement of the sun too. Well done (10)</td>', 'THE perfect wedding shot. I love the wide angle distortion and the composition and burning set this image apart from a lot of the others in this challenge. Beautiful contrast and the sepia tones work very well here. Great placement of the sun too. Well done (10)', '2004-07-20 06:23:39.000000', NULL, 1),
(817880, 91237, 17233, '<td valign="top">Unfortunately contrast is what this image lacks. Looks like fairly inclement weather which doesn''t help with contrast either. The ledge running across the bottom is really distracting and has no real value compositionally. The Aloe at left is also seemingly out of place and the dead bits detract from it also.</td>', 'Unfortunately contrast is what this image lacks. Looks like fairly inclement weather which doesn''t help with contrast either. The ledge running across the bottom is really distracting and has no real value compositionally. The Aloe at left is also seemingly out of place and the dead bits detract from it also.', '2004-07-20 06:35:37.000000', NULL, 1),
(817921, 92075, 22659, '<td valign="top">Were you going by the time on your watch or what the clock tower says? It looks like it says 11:13 to me.  The pic is pretty well balanced though.</td>', 'Were you going by the time on your watch or what the clock tower says? It looks like it says 11:13 to me.  The pic is pretty well balanced though.', '2004-07-20 07:36:22.000000', NULL, 1),
(817930, 91033, 22659, '<td valign="top">The left ball is a tad higher than the right ball. I always notice things like that being a mason/bricklayer. I like the way you have the male and female signs in the background. I didn''t see them at first because I  was distracted by the ball height difference but I think it was a great addition to your pic. Very nice pic -9</td>', 'The left ball is a tad higher than the right ball. I always notice things like that being a mason/bricklayer. I like the way you have the male and female signs in the background. I didn''t see them at first because I  was distracted by the ball height difference but I think it was a great addition to your pic. Very nice pic -9', '2004-07-20 07:49:00.000000', NULL, 1),
(817931, 90794, 22659, '<td valign="top">I''d never ride a bike with no hands if I had my camera with me. I''d be to afraid of wiping out and smashing my camera. lol Great original idea for this challenge.</td>', 'I''d never ride a bike with no hands if I had my camera with me. I''d be to afraid of wiping out and smashing my camera. lol Great original idea for this challenge.', '2004-07-20 07:53:12.000000', NULL, 1),
(817938, 91910, 20407, '<td valign="top">What a cute model :-)</td>', 'What a cute model :-)', '2004-07-20 08:14:37.000000', NULL, 1),
(817946, 92222, 20407, '<td valign="top">Good one, I love making the enterprise out of stuff :)</td>', 'Good one, I love making the enterprise out of stuff :)', '2004-07-20 08:31:20.000000', NULL, 1),
(817959, 92157, 164, '<td valign="top">Good idea.</td>', 'Good idea.', '2004-07-20 08:40:46.000000', NULL, 1),
(817963, 91976, 20407, '<td valign="top">I thought this was sorta cool, then I saw the cat in the window. Excellent timing. I''ve added it to my favourites.  8</td>', 'I thought this was sorta cool, then I saw the cat in the window. Excellent timing. I''ve added it to my favourites.  8', '2004-07-20 08:53:43.000000', NULL, 1),
