(818033, 91583, 164, '<td valign="top">White door looks yellowish. Handle too dark onmy screen.</td>', 'White door looks yellowish. Handle too dark onmy screen.', '2004-07-20 10:46:56.000000', NULL, 1),
(818044, 90794, 22010, '<td valign="top">Great shot! How you managed to not have obscene camera shake while maintaing forward motion is beyond me and/or my lenses. Nice.</td>', 'Great shot! How you managed to not have obscene camera shake while maintaing forward motion is beyond me and/or my lenses. Nice.', '2004-07-20 11:12:02.000000', NULL, 1),
(818046, 92037, 16241, '<td valign="top">exceptional</td>', 'exceptional', '2004-07-20 11:16:29.000000', NULL, 1),
(818058, 91097, 12802, '<td valign="top">Good idea for the challenge, good DOF and white balance, the dimples in the ball are nice and clear.<br/> <br/>A few things to maybe score higher...  The green bits at the bottom are distracting and the Absolutely Straight text would have been nicer if it was actually straight... 8</td>', 'Good idea for the challenge, good DOF and white balance, the dimples in the ball are nice and clear. A few things to maybe score higher...  The green bits at the bottom are distracting and the Absolutely Straight text would have been nicer if it was actually straight... 8', '2004-07-20 11:46:20.000000', NULL, 1),
(818073, 92098, 19708, '<td valign="top">Great job on this "dual exposure" shot.<br/>Soft, delicate &amp; classy.<br/>One of my favorites in this challenge! ((9))</td>', 'Great job on this "dual exposure" shot.Soft, delicate & classy.One of my favorites in this challenge! ((9))', '2004-07-20 12:00:50.000000', NULL, 1),
