(821914, 92212, 8367, '<td valign="top">Great shot. I hope your camera didn''t get wet!</td>', 'Great shot. I hope your camera didn''t get wet!', '2004-07-22 13:09:36.000000', NULL, 1),
(821920, 91761, 8367, '<td valign="top">Woo hoo. Looks like fun.  The upside down hair makes the shot and convinces me that you didn''t just flip it.  Great capture.</td>', 'Woo hoo. Looks like fun.  The upside down hair makes the shot and convinces me that you didn''t just flip it.  Great capture.', '2004-07-22 13:15:43.000000', NULL, 1),
