(822103, 92165, 17937, '<td valign="top">You using glue?  Nice photo. (8)</td>', 'You using glue?  Nice photo. (8)', '2004-07-22 16:07:50.000000', NULL, 1),
(822151, 91987, 8816, '<td valign="top">I think what could solve the feeling of the image being slightly unnatural is using a straight b&amp;w instead of a sepia tone.  I love the artistry of this image, and the spectacular background you managed to capture it on, but in an image such as this believability is a must, and I have trouble visualizing this in real life.  8</td>', 'I think what could solve the feeling of the image being slightly unnatural is using a straight b&w instead of a sepia tone.  I love the artistry of this image, and the spectacular background you managed to capture it on, but in an image such as this believability is a must, and I have trouble visualizing this in real life.  8', '2004-07-22 17:02:45.000000', NULL, 1),
(822162, 91244, 8891, '<td valign="top">GO Philly!....BW was a good choice for this, well composed and nice tones throughout.</td>', 'GO Philly!....BW was a good choice for this, well composed and nice tones throughout.', '2004-07-22 17:30:52.000000', NULL, 1),
(822179, 91581, 10041, '<td valign="top">Nice !</td>', 'Nice !', '2004-07-22 17:46:18.000000', NULL, 1),
(822191, 91667, 19641, '<td valign="top">I like this because it is creative.  It''s not what people think of first when they think of balance.</td>', 'I like this because it is creative.  It''s not what people think of first when they think of balance.', '2004-07-22 18:04:48.000000', NULL, 1),
(822252, 91838, 22459, '<td valign="top">This meets the challenge, as a non-cat lover i get the urge to push him in!. (thats terrible isn''t it) but for picture to evoke those feelings it must have something. well done.</td>', 'This meets the challenge, as a non-cat lover i get the urge to push him in!. (thats terrible isn''t it) but for picture to evoke those feelings it must have something. well done.', '2004-07-22 18:43:38.000000', NULL, 1),
(822266, 91838, 10263, '<td valign="top">Yep he got it figured out. I love it. A fun photo thats nicely done.</td>', 'Yep he got it figured out. I love it. A fun photo thats nicely done.', '2004-07-22 18:59:49.000000', NULL, 1),
(822268, 90815, 10263, '<td valign="top">Beautifully balanced. The saw-like decorations are a nice touch. A little bit of compression residue on the pillers. Nice composition.</td>', 'Beautifully balanced. The saw-like decorations are a nice touch. A little bit of compression residue on the pillers. Nice composition.', '2004-07-22 19:01:58.000000', NULL, 1),
(822270, 92060, 10263, '<td valign="top">Thats some balance. Nice capture. Pretty colors.</td>', 'Thats some balance. Nice capture. Pretty colors.', '2004-07-22 19:02:58.000000', NULL, 1),
(822274, 91987, 22310, '<td valign="top">Well done!  Great DOF and contrast.</td>', 'Well done!  Great DOF and contrast.', '2004-07-22 19:04:49.000000', NULL, 1),
(822276, 92170, 22310, '<td valign="top">Nice lighting on the leaf, background a little flat but nice overall excellent shot.</td>', 'Nice lighting on the leaf, background a little flat but nice overall excellent shot.', '2004-07-22 19:07:12.000000', NULL, 1),
(822277, 90674, 22310, '<td valign="top">Cool idea, excellent title.  A little more DOF and the top of the filter would be in focus.</td>', 'Cool idea, excellent title.  A little more DOF and the top of the filter would be in focus.', '2004-07-22 19:08:25.000000', NULL, 1),
(822280, 92157, 22310, '<td valign="top">Great DOF.  One minute ealier and you would have caught it on the hour to line up the minute hand.  Over all one of my favourites.</td>', 'Great DOF.  One minute ealier and you would have caught it on the hour to line up the minute hand.  Over all one of my favourites.', '2004-07-22 19:10:03.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(822282, 91366, 22310, '<td valign="top">Great lighting!  Nice texture on the eggs.  I like the red ring on the bowl.</td>', 'Great lighting!  Nice texture on the eggs.  I like the red ring on the bowl.', '2004-07-22 19:11:23.000000', NULL, 1),
(822283, 92007, 22310, '<td valign="top">Cool idea.  I like the shallow DOF.  It make the board look like it extends to infinity.</td>', 'Cool idea.  I like the shallow DOF.  It make the board look like it extends to infinity.', '2004-07-22 19:12:45.000000', NULL, 1),
(822285, 91976, 22310, '<td valign="top">I missed the cat the first time I looked at this photo.  You might lighten that area up a little.  Still one of the better ones.</td>', 'I missed the cat the first time I looked at this photo.  You might lighten that area up a little.  Still one of the better ones.', '2004-07-22 19:13:46.000000', NULL, 1),
(822289, 92055, 22310, '<td valign="top">Well done.  The B&amp;W works very well here.</td>', 'Well done.  The B&W works very well here.', '2004-07-22 19:15:05.000000', NULL, 1),
(822291, 91973, 22310, '<td valign="top">Nice composition, whimsical.  Shallow DOF is the key.</td>', 'Nice composition, whimsical.  Shallow DOF is the key.', '2004-07-22 19:15:51.000000', NULL, 1),
(822297, 92209, 22310, '<td valign="top">Nice image but  I don''t recognize what he is standing on.  This detracts from the sense of balance.  Still a great shot.</td>', 'Nice image but  I don''t recognize what he is standing on.  This detracts from the sense of balance.  Still a great shot.', '2004-07-22 19:22:07.000000', NULL, 1),
(822299, 92180, 22310, '<td valign="top">The most dreaded of all balance.  Cool idea, great execution.</td>', 'The most dreaded of all balance.  Cool idea, great execution.', '2004-07-22 19:23:06.000000', NULL, 1),
(822304, 91281, 10263, '<td valign="top">Wonderful colors. Fits the challenge well. Love the abstract feel to it.</td>', 'Wonderful colors. Fits the challenge well. Love the abstract feel to it.', '2004-07-22 19:29:21.000000', NULL, 1),
