(824134, 91984, 2764, '<td valign="top">white balance?  Great image - lots of tension but his hands are a funny color.</td>', 'white balance?  Great image - lots of tension but his hands are a funny color.', '2004-07-24 14:48:07.000000', NULL, 1),
